CREATE OR REPLACE FUNCTION public.deed_aura_of(p_world uuid, p_keeper uuid, p_post bigint, p_channel text)
 RETURNS double precision
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return (
select coalesce((select case when bool_or(e.mul = 0) then 0 else exp(sum(ln(nullif(e.mul, 0)) order by o.id, e.trait)) end
